glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = vec4(a_position, 1);
  pos = cc_matViewProj * pos;

  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif

  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif

uniform PROPERTIES {
  vec4 selectTargetColor;
  vec4 selectTint;
};

vec3 applySelectBaseGlow(vec3 baseRgb, float alpha, vec3 glowRgb, float amount,
    float mulAddWeight, float softAddWeight, float screenWeight) {
  float t = clamp(amount, 0.0, 1.0);
  if (t <= 0.0001) {
    return baseRgb;
  }
  float mulW = max(0.0, mulAddWeight);
  float softW = max(0.0, softAddWeight);
  float scrW = clamp(screenWeight, 0.0, 2.0);
  vec3 glow = max(glowRgb, vec3(0.0));

  vec3 lit = baseRgb * (1.0 + glow * (t * mulW));

  lit += glow * clamp(alpha, 0.0, 1.0) * (t * softW);

  vec3 screened = lit + glow - lit * glow;
  lit = mix(lit, screened, clamp(t * scrW, 0.0, 1.0));

  return lit;
}

void main () {
  vec4 o = vec4(1.0, 1.0, 1.0, 1.0);

  #if USE_TEXTURE
    o *= texture2D(texture, v_uv0);
  #endif

  #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif

  o *= v_color;

  float amount = clamp(selectTint.x, 0.0, 1.0);
  float mulAddWeight = selectTint.y;
  float softAddWeight = selectTint.z;
  float screenWeight = selectTint.w;

  if (mulAddWeight <= 0.0 && softAddWeight <= 0.0 && screenWeight <= 0.0) {
    mulAddWeight = 1.2;
    softAddWeight = 0.4;
    screenWeight = 0.25;
  }

  if (amount > 0.0001 && o.a > 0.0001) {
    float a = clamp(o.a, 0.0, 1.0);

    vec3 baseRgb = o.rgb / max(a, 0.0001);
    vec3 lit = applySelectBaseGlow(baseRgb, a, selectTargetColor.rgb, amount,
        mulAddWeight, softAddWeight, screenWeight);

    o.rgb = lit * a;
  }

  gl_FragColor = o;
}

